type Progress = { lessonId: string; position: number; updatedAt: number };
export function latestProgress(a: Progress, b: Progress) {
  if (a.lessonId !== b.lessonId) throw new Error('다른 강의입니다.');
  return a.updatedAt >= b.updatedAt ? a : b;
}
// 기기 시각 대신 서버 버전을 사용하고 이수 판정은 별도 정책으로 처리합니다.

export function scoreChoice(answerIds: string[], expectedIds: string[]) {
  const actual = new Set(answerIds);
  const expected = new Set(expectedIds);
  return actual.size === expected.size && [...actual].every(id => expected.has(id));
}
// 정답 목록은 서버에서만 읽고 답안 ID의 문항 소속을 먼저 확인합니다.

type Submission = { deadline: number; submittedAt: number | null };
export function submissionState(item: Submission) {
  if (item.submittedAt === null) return 'draft';
  return item.submittedAt <= item.deadline ? 'submitted' : 'late';
}
// 제출 시각은 브라우저 입력이 아니라 서버의 접수 시각을 사용합니다.

type Criterion = { max: number; score: number | null };
export function rubricTotal(items: Criterion[]) {
  if (items.some(item => item.score === null)) return null;
  for (const item of items)
    if (!Number.isFinite(item.score) || item.score! < 0 || item.score! > item.max)
      throw new Error('배점 범위를 벗어났습니다.');
  return items.reduce((total, item) => total + item.score!, 0);
}

type Evidence = { lessonsDone: boolean; assignmentsDone: boolean; score: number | null };
export function completion(e: Evidence, passScore: number) {
  const missing = [];
  if (!e.lessonsDone) missing.push('필수 학습');
  if (!e.assignmentsDone) missing.push('과제');
  if (e.score === null) missing.push('채점 대기');
  else if (e.score < passScore) missing.push('평가 기준');
  return { complete: missing.length === 0, missing };
}

type Certificate = { id: string; courseId: string; revokedAt: number | null };
export function publicVerification(item: Certificate) {
  return { id: item.id, courseId: item.courseId,
    status: item.revokedAt === null ? 'valid' : 'revoked' };
}
